class Solution {
public:
    int numRabbits(vector<int>& answers) {
        unordered_map<int, int> counts;
        for (int a : answers) counts[a]++;
        int total = 0;
        for (auto [k, count] : counts) {
            int group_size = k + 1;
            int num_groups = (count + k) / group_size;
            total += num_groups * group_size;
        }
        return total;
    }
};

class Solution {
    public int numRabbits(int[] answers) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int a : answers) counts.put(a, counts.getOrDefault(a, 0) + 1);
        int total = 0;
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            int k = entry.getKey();
            int count = entry.getValue();
            int groupSize = k + 1;
            int numGroups = (count + k) / groupSize;
            total += numGroups * groupSize;
        }
        return total;
    }
}

var numRabbits = function(answers) {
    const counts = new Map();
    for (const a of answers) {
        counts.set(a, (counts.get(a) || 0) + 1);
    }
    let total = 0;
    for (const [k, count] of counts.entries()) {
        const groupSize = k + 1;
        const numGroups = Math.floor((count + k) / groupSize);
        total += numGroups * groupSize;
    }
    return total;
};
